 * The lexer. `scan(source)` turns UTF-8 source text (already decoded to a
 * JS string) into an array of tokens, or throws a `ScanError` at the first
 * point the input stops scanning.
 */

export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

const isDecDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHexDigit = (c) => c !== undefined && /[0-9a-fA-F]/.test(c)
const isBinDigit = (c) => c === '0' || c === '1'
const isOctDigit = (c) => c !== undefined && c >= '0' && c <= '7'
const isIdentStart = (c) => c !== undefined && /[A-Za-z_]/.test(c)
const isIdentContinue = (c) => c !== undefined && /[A-Za-z0-9_]/.test(c)

class Scanner {
  constructor(src) {
    this.chars = Array.from(src)
    this.i = 0
    this.line = 1
    this.col = 1
  }

  eof() {
    return this.i >= this.chars.length
  }

  peek(k = 0) {
    return this.chars[this.i + k]
  }

  advance() {
    const c = this.chars[this.i++]
    if (c === '\n') {
      this.line += 1
      this.col = 1
    } else if (c === '\t') {
      this.col = Math.floor((this.col - 1) / 4 + 1) * 4 + 1
    } else {
      this.col += 1
    }
    return c
  }
}

function skipTrivia(s) {
  for (;;) {
    if (s.eof()) return
    const c = s.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      s.advance()
      continue
    }
    if (c === '/' && s.peek(1) === '/') {
      while (!s.eof() && s.peek() !== '\n') s.advance()
      continue
    }
    if (c === '/' && s.peek(1) === '*') {
      const startLine = s.line
      const startCol = s.col
      s.advance()
      s.advance()
      let depth = 1
      while (depth > 0) {
        if (s.eof()) throw new ScanError(startLine, startCol, 'unterminated block comment')
        const cc = s.peek()
        if (cc === '/' && s.peek(1) === '*') {
          s.advance()
          s.advance()
          depth += 1
        } else if (cc === '*' && s.peek(1) === '/') {
          s.advance()
          s.advance()
          depth -= 1
        } else {
          s.advance()
        }
      }
      continue
    }
    return
  }
}

function consumeDigitRun(s, isDigit) {
  let digits = 0
  while (!s.eof()) {
    const c = s.peek()
    if (isDigit(c)) {
      s.advance()
      digits += 1
      continue
    }
    if (c === '_') {
      const prev = s.chars[s.i - 1]
      const next = s.chars[s.i + 1]
      if (isDigit(prev) && isDigit(next)) {
        s.advance()
        continue
      }
      break
    }
    break
  }
  return digits
}

function scanIdent(s) {
  const line = s.line
  const col = s.col
  const startIdx = s.i
  while (isIdentContinue(s.peek())) s.advance()
  const text = s.chars.slice(startIdx, s.i).join('')
  return { line, col, kind: KEYWORDS.has(text) ? 'keyword' : 'ident', text }
}

function scanNumber(s) {
  const line = s.line
  const col = s.col
  const startIdx = s.i
  const c0 = s.peek()
  const c1 = s.peek(1)
  let invalid = false

  if (c0 === '0' && (c1 === 'x' || c1 === 'X')) {
    s.advance()
    s.advance()
    if (consumeDigitRun(s, isHexDigit) === 0) invalid = true
  } else if (c0 === '0' && (c1 === 'b' || c1 === 'B')) {
    s.advance()
    s.advance()
    if (consumeDigitRun(s, isBinDigit) === 0) invalid = true
  } else if (c0 === '0' && (c1 === 'o' || c1 === 'O')) {
    s.advance()
    s.advance()
    if (consumeDigitRun(s, isOctDigit) === 0) invalid = true
  } else {
    consumeDigitRun(s, isDecDigit)
    if (s.peek() === '.' && isDecDigit(s.peek(1))) {
      s.advance()
      consumeDigitRun(s, isDecDigit)
    }
    if (s.peek() === 'e' || s.peek() === 'E') {
      const n1 = s.peek(1)
      if (isDecDigit(n1)) {
        s.advance()
        consumeDigitRun(s, isDecDigit)
      } else if ((n1 === '+' || n1 === '-') && isDecDigit(s.peek(2))) {
        s.advance()
        s.advance()
        consumeDigitRun(s, isDecDigit)
      }
    }
  }

  if (isIdentContinue(s.peek())) invalid = true

  if (invalid) {
    while (isIdentContinue(s.peek())) s.advance()
    const text = s.chars.slice(startIdx, s.i).join('')
    throw new ScanError(line, col, `invalid number ${text}`)
  }

  const text = s.chars.slice(startIdx, s.i).join('')
  return { line, col, kind: 'number', text }
}

function scanString(s) {
  const line = s.line
  const col = s.col
  s.advance() // opening quote
  let decoded = ''
  for (;;) {
    if (s.eof()) throw new ScanError(line, col, 'unterminated string')
    const c = s.peek()
    if (c === '"') {
      s.advance()
      break
    }
    if (c === '\n') throw new ScanError(s.line, s.col, 'newline in string')
    if (c === '\\') {
      const bsLine = s.line
      const bsCol = s.col
      s.advance() // backslash
      if (s.eof()) throw new ScanError(line, col, 'unterminated string')
      const e = s.peek()
      if (e === 'n') {
        decoded += '\n'
        s.advance()
      } else if (e === 't') {
        decoded += '\t'
        s.advance()
      } else if (e === 'r') {
        decoded += '\r'
        s.advance()
      } else if (e === '\\') {
        decoded += '\\'
        s.advance()
      } else if (e === '"') {
        decoded += '"'
        s.advance()
      } else if (e === '0') {
        decoded += '\0'
        s.advance()
      } else if (e === 'x') {
        s.advance() // x
        const h1 = s.peek()
        const h2 = s.peek(1)
        if (!isHexDigit(h1) || !isHexDigit(h2)) throw new ScanError(bsLine, bsCol, 'invalid escape \\x')
        s.advance()
        s.advance()
        decoded += String.fromCharCode(parseInt(h1 + h2, 16))
      } else if (e === 'u') {
        s.advance() // u
        if (s.peek() !== '{') throw new ScanError(bsLine, bsCol, 'invalid escape \\u')
        s.advance() // {
        let hex = ''
        while (isHexDigit(s.peek())) hex += s.advance()
        if (hex.length === 0) throw new ScanError(bsLine, bsCol, 'invalid escape \\u')
        if (s.peek() !== '}') throw new ScanError(bsLine, bsCol, 'invalid escape \\u')
        s.advance() // }
        const cp = parseInt(hex, 16)
        if (cp > 0x10ffff) throw new ScanError(bsLine, bsCol, 'invalid escape \\u')
        decoded += String.fromCodePoint(cp)
      } else {
        throw new ScanError(bsLine, bsCol, `invalid escape \\${e}`)
      }
      continue
    }
    decoded += c
    s.advance()
  }
  return { line, col, kind: 'string', text: decoded }
}

function scanRawString(s) {
  const line = s.line
  const col = s.col
  s.advance() // r
  s.advance() // opening quote
  let text = ''
  for (;;) {
    if (s.eof()) throw new ScanError(line, col, 'unterminated string')
    const c = s.peek()
    if (c === '"') {
      s.advance()
      break
    }
    text += c
    s.advance()
  }
  return { line, col, kind: 'rawstring', text }
}

function scanPunct(s) {
  const line = s.line
  const col = s.col
  const c0 = s.peek()
  const c1 = s.peek(1)
  const two = c1 === undefined ? '' : c0 + c1
  if (TWO_CHAR_PUNCT.has(two)) {
    s.advance()
    s.advance()
    return { line, col, kind: 'punct', text: two }
  }
  if (ONE_CHAR_PUNCT.has(c0)) {
    s.advance()
    return { line, col, kind: 'punct', text: c0 }
  }
  throw new ScanError(line, col, `unexpected character ${c0}`)
}

function scanToken(s) {
  const c = s.peek()
  if (isIdentStart(c)) return scanIdent(s)
  if (isDecDigit(c)) return scanNumber(s)
  if (c === '"') return scanString(s)
  if (c === 'r' && s.peek(1) === '"') return scanRawString(s)
  return scanPunct(s)
}

export function scan(source) {
  const s = new Scanner(source)
  const tokens = []
  for (;;) {
    skipTrivia(s)
    if (s.eof()) break
    tokens.push(scanToken(s))
  }
  return tokens
}
"}

