/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { scan, ScanError } from './lexer.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    fail('usage: cli.js tokens|stats')
    return
  }
  const mode = args[0]
  const source = await readStdin()

  let tokens
  try {
    tokens = scan(source)
  } catch (err) {
    if (err instanceof ScanError) {
      fail(`${err.line}:${err.col}: ${err.reason}`)
      return
    }
    throw err
  }

  const lines = []
  if (mode === 'tokens') {
    for (const t of tokens) {
      const body = t.kind === 'string' || t.kind === 'rawstring' ? JSON.stringify(t.text) : t.text
      lines.push(`${t.line}:${t.col} ${t.kind} ${body}`)
    }
  } else {
    const counts = Object.fromEntries(STAT_KINDS.map((k) => [k, 0]))
    for (const t of tokens) counts[t.kind] += 1
    for (const k of STAT_KINDS) lines.push(`${k} ${counts[k]}`)
    lines.push(`total ${tokens.length}`)
  }
  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
}

main()
"}

