function scanToken(s) {
  const c = s.peek()
  if (isIdentStart(c)) return scanIdent(s)
  if (isDecDigit(c)) return scanNumber(s)
  if (c === '"') return scanString(s)
  if (c === 'r' && s.peek(1) === '"') return scanRawString(s)
  return scanPunct(s)
}

diffs.newText:
function scanToken(s) {
  const c = s.peek()
  if (c === 'r' && s.peek(1) === '"') return scanRawString(s)
  if (isIdentStart(c)) return scanIdent(s)
  if (isDecDigit(c)) return scanNumber(s)
  if (c === '"') return scanString(s)
  return scanPunct(s)
}
